  { name: 'Histoire-géographie', icon: '⌖', series: [{name:'Toutes les questions', files:['tout_melange_histoire.csv']}, {name:'Culture générale', files:['histoire_gen.csv']}, {name:'Histoire term', files:['histoire_term.csv']}] },
  { name: 'Tout mélange', icon: '✳', series: [{name:'Toutes les questions', all:true}] }
