const assetNames = ['anglais.csv','francais.csv','histoire_gen.csv','histoire_term.csv','maths_1e.csv','maths_term.csv','physique_1e.csv','physique_gen.csv','physique_term.csv','tout_melange_histoire.csv','tout_melange_math.csv','tout_melange_physique.csv','tout_melange.csv'];
const dbKey='revision-express-pwa-v1';
let db = JSON.parse(localStorage.getItem(dbKey)||'{"categories":[],"series":{}}');
db.categories??=[];db.series??={};db.subcategories??=[];db.deletedBuiltinCategories??=[];db.builtinCategoryNames??={};db.deletedBuiltinSeries??=[];db.builtinSeriesNames??={};db.builtinSeriesLocations??={};db.builtinSeriesOrder??={};db.seriesOrder??={};
let currentCategory=null, session=[], qIndex=0, selected=-1, locked=false, timer=null, left=300, sessionScore=0;
