let activeDrag=null,dragClickGuardUntil=0;
let deferredInstall=null;
let swRegistration=null,updateAvailable=false,reloadForUpdate=false;
function save(){localStorage.setItem(dbKey,JSON.stringify(db));}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function subcategoryById(id){return db.subcategories.find(item=>item.id===id);}
function builtinSeriesId(category,series){return `${category}::${series.name}`;}
function seriesOrderKey(series){if(series.builtinId)return `builtin:${series.builtinId}`;if(series.all)return 'all:questions';series.localId??=crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;return `custom:${series.localId}`;}
function isBuiltinCategory(id){return builtins.some(item=>item.name===id);}
function builtinCategoryVisible(id){return isBuiltinCategory(id)&&!db.deletedBuiltinCategories.includes(id);}
function builtinSeriesDefinition(id){for(const category of builtins)for(const series of category.series)if(builtinSeriesId(category.name,series)===id)return{category:category.name,series};return null;}
function builtinSeriesRecords(category){const definition=builtins.find(item=>item.name===category);const records=(definition?.series||[]).map((series,index)=>({...series,builtin:true,builtinId:builtinSeriesId(category,series),name:db.builtinSeriesNames[builtinSeriesId(category,series)]||series.name,_sourceIndex:index})).filter(series=>!db.deletedBuiltinSeries.includes(series.builtinId)&&!db.builtinSeriesLocations[series.builtinId]);const order=db.builtinSeriesOrder[category]||[];records.sort((a,b)=>{const ai=order.indexOf(a.builtinId),bi=order.indexOf(b.builtinId);if(ai<0&&bi<0)return a._sourceIndex-b._sourceIndex;return (ai<0?Infinity:ai)-(bi<0?Infinity:bi);});return records.map(({_sourceIndex,...series})=>series);}
function categoryLabel(id){return subcategoryById(id)?.name||db.builtinCategoryNames[id]||id;}
function categoryPath(id){const labels=[categoryLabel(id)];let parent=subcategoryById(id)?.parent;while(parent){const parentNode=subcategoryById(parent);if(parentNode){labels.unshift(parentNode.name);parent=parentNode.parent;}else{labels.unshift(parent);break;}}return labels.join(' · ');}
function childCategories(parent){return db.subcategories.filter(item=>item.parent===parent);}
function categoryTreeKeys(parent){return [parent,...childCategories(parent).flatMap(item=>categoryTreeKeys(item.id))];}
function customNames(){return [...new Set([...db.categories,...Object.keys(db.series).filter(key=>!subcategoryById(key)&&!isBuiltinCategory(key))])].filter(name=>!db.deletedBuiltinCategories.includes(name)).sort((a,b)=>a.localeCompare(b,'fr'));}
function show(view,addHistory=true){if(!['homeView','categoryView','quizView'].includes(view))return;const categoryState=view==='categoryView'?currentCategory:null;const shouldPush=addHistory&&(view!==currentView||(view==='categoryView'&&history.state?.category!==categoryState));if(shouldPush)history.pushState({revisionExpressView:view,category:categoryState},'',location.href);if(currentView==='quizView'&&view!=='quizView')clearInterval(timer);currentView=view;['homeView','categoryView','quizView'].forEach(id=>$(id).classList.toggle('hidden',id!==view));window.scrollTo(0,0);}
history.replaceState({revisionExpressView:'homeView',category:null},'',location.href);
window.addEventListener('popstate',event=>{const target=event.state?.revisionExpressView;if(!target)return;if(target==='categoryView'&&event.state.category){const key=event.state.category;if((builtinCategoryVisible(key)||db.categories.includes(key)||subcategoryById(key))){openCategory(key,false);return;}show('homeView',false);return;}if(currentView==='quizView'&&target!=='quizView')clearInterval(timer);show(target,false);});
function renderHome(){const host=$('categoryGrid');host.innerHTML='';const entries=[...builtins.filter(c=>builtinCategoryVisible(c.name)&&!subcategoryById(c.name)).map(c=>({...c,custom:false,name:c.name})),...customNames().filter(name=>!isBuiltinCategory(name)).map(name=>({name,icon:'✳',custom:true,series:[]}))];for(const c of entries){const n=c.custom?(db.series[c.name]||[]).filter(s=>!s.builtinId).length:builtinSeriesRecords(c.name).length+(db.series[c.name]||[]).length;const tile=document.createElement('button');tile.className='category-tile';tile.innerHTML=`<span class="tile-icon">${c.icon}</span><div class="tile-title">${esc(categoryLabel(c.name))}</div><div class="tile-sub">${c.custom?`${n} série${n===1?'':'s'} personnalisée${n===1?'':'s'}`:`${n} série${n===1?'':'s'}`}</div>`;bindCategoryTile(tile,c.name);host.append(tile);} }
async function csv(file){try{const res=await fetch(`app/src/main/assets/${file}`);if(!res.ok)return[];return parseCsv(await res.text());}catch{return[]}}
function parseCsv(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).slice(1);return lines.map(line=>{const cells=[];let v='',quote=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&quote&&line[i+1]==='"'){v+='"';i++;}else if(c==='"')quote=!quote;else if(c===','&&!quote){cells.push(v);v='';}else v+=c;}cells.push(v);if(cells.length<6)return null;const correct=Number(cells[5])-1;return correct>=0&&correct<4?{question:cells[0],options:cells.slice(1,5),correct}:null;}).filter(Boolean);}
function bindCategoryTile(tile,name){tile.onclick=e=>{if(Date.now()<dragClickGuardUntil){e.preventDefault();e.stopPropagation();return;}openCategory(name);};let hold,opened=false;tile.onpointerdown=e=>{if(e.target.closest('.drag-handle'))return;opened=false;hold=setTimeout(()=>{opened=true;categoryActions(name);},650);};['pointerup','pointerleave','pointercancel'].forEach(ev=>tile.addEventListener(ev,()=>clearTimeout(hold)));tile.oncontextmenu=e=>{e.preventDefault();clearTimeout(hold);if(e.target.closest('.drag-handle'))return;if(!opened){opened=true;categoryActions(name);}};}
function openCategory(name,addHistory=true){currentCategory=name;$('categoryTitle').textContent=categoryPath(name);const parent=subcategoryById(name)?.parent;$('backHome').textContent=parent?`← ${categoryLabel(parent)}`:'← Menu principal';const subHost=$('subcategoryGrid');subHost.innerHTML='';for(const child of childCategories(name)){const tile=document.createElement('button');tile.className='category-tile subcategory-tile';const n=(db.series[child.id]||[]).length+builtinSeriesRecords(child.id).length;tile.innerHTML=`<span class="drag-handle" aria-label="Glisser pour réorganiser ou déplacer">⠿</span><span class="tile-icon">↳</span><div class="tile-title">${esc(child.name)}</div><div class="tile-sub">${n} série${n===1?'':'s'} · Sous-catégorie</div>`;tile._dragInfo={type:'subcategory',id:child.id,parent:name,tile};bindCategoryTile(tile,child.id);enableDragHandle(tile);subHost.append(tile);}$('seriesGrid').innerHTML='';const built=builtins.find(c=>c.name===name);let list=built?builtinSeriesRecords(name):[];if(!list.some(s=>s.name==='Toutes les questions'))list.unshift({name:'Toutes les questions',all:true,builtin:true});list.push(...(db.series[name]||[]));const seriesOrder=db.seriesOrder[name]||[];if(seriesOrder.length)list.sort((a,b)=>{const ai=seriesOrder.indexOf(seriesOrderKey(a)),bi=seriesOrder.indexOf(seriesOrderKey(b));return(ai<0?Infinity:ai)-(bi<0?Infinity:bi);});list.forEach(s=>{const b=document.createElement('button');b.className='series-tile'+(s.all?' all':'');const movable=!!s.questions||!!s.builtinId;b.innerHTML=`${movable?'<span class="drag-handle" aria-label="Glisser pour réorganiser ou déplacer">⠿</span>':''}<span class="tile-arrow">→</span><div class="tile-title">${esc(s.name)}</div><div class="tile-sub">${s.all?'20 questions aléatoires':s.questions?`${s.count} questions`:''}</div>`;b.onclick=e=>{if(Date.now()<dragClickGuardUntil){e.preventDefault();e.stopPropagation();return;}launchSeries(name,s);};if(movable){b._dragInfo={type:'series',category:name,series:s,tile:b};enableDragHandle(b);}let hold,opened=false;b.onpointerdown=e=>{if(e.target.closest('.drag-handle'))return;opened=false;hold=setTimeout(()=>{opened=true;seriesActions(name,s);},650);};['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>clearTimeout(hold)));b.oncontextmenu=e=>{e.preventDefault();if(e.target.closest('.drag-handle'))return;if(!opened)seriesActions(name,s);};$('seriesGrid').append(b);});show('categoryView',addHistory);}
function launchSeries(category,s){if(s.all)startAll(category);else if(s.questions)startCustom(category,s);else startBuiltIn(category,s);}
function seriesActions(category,series){
  const custom=!!series.questions,manageable=custom||!!series.builtinId;
  const body=`<p>${custom?`${esc(series.count)} questions · Série personnalisée`:'Série installée dans l’application.'}</p><div class="dialog-actions stack"><button type="button" class="button primary wide" data-act="play">Lancer la série</button><button type="button" class="button secondary wide" data-act="share">Partager la série</button>${manageable?`<button type="button" class="button secondary wide" data-act="rename">Renommer la série</button><button type="button" class="button secondary wide" data-act="move">Déplacer vers…</button>${custom?'<button type="button" class="button secondary wide" data-act="edit">Modifier la série</button>':''}${series.all?'':'<button type="button" class="button secondary wide" data-act="merge">Fusionner avec une autre série</button>'}<button type="button" class="button secondary wide" data-act="delete">Supprimer la série</button>`:''}<button type="button" class="button secondary wide" data-act="close">Fermer</button></div>`;
  const d=dialog(series.name,body);d.showModal();
  d.querySelector('[data-act="close"]').onclick=()=>d.close();
  d.querySelector('[data-act="play"]').onclick=()=>{d.close();launchSeries(category,series);};
  d.querySelector('[data-act="share"]').onclick=async()=>{d.close();try{const qs=await seriesQuestions(category,series);await publishShare({category:categoryPath(category),series:[{name:series.name,count:series.count||qs.length||20,questions:qs}]});}catch(e){alert(`Partage impossible : ${e.message}`);}};
  d.querySelector('[data-act="rename"]')?.addEventListener('click',()=>{d.close();renameSeries(category,series);});
  d.querySelector('[data-act="move"]')?.addEventListener('click',()=>{d.close();moveSeries(category,series);});
  d.querySelector('[data-act="edit"]')?.addEventListener('click',()=>{d.close();editSeries(category,series);});
  d.querySelector('[data-act="merge"]')?.addEventListener('click',()=>{d.close();chooseSeriesToMerge(category,series);});
  d.querySelector('[data-act="delete"]')?.addEventListener('click',()=>{d.close();if(!confirm(`Supprimer « ${series.name} » ?`))return;removeSeriesFromStorage(category,series);save();renderHome();openCategory(category);});
}
async function seriesQuestions(category,series){if(series.all)return categoryPool(category);if(series.questions)return [...series.questions];const definition=series.builtinId?builtinSeriesDefinition(series.builtinId)?.series:null;const files=series.files||definition?.files||[];return (await Promise.all(files.map(csv))).flat();}
function removeSeriesFromStorage(category,series){if(series.builtinId){if(!db.deletedBuiltinSeries.includes(series.builtinId))db.deletedBuiltinSeries.push(series.builtinId);delete db.builtinSeriesLocations[series.builtinId];for(const group of Object.values(db.series))for(let index=group.length-1;index>=0;index--)if(group[index].builtinId===series.builtinId)group.splice(index,1);}else{db.series[category]=(db.series[category]||[]).filter(item=>item!==series);}}
function availableMergeTargets(category,series){const keys=[...new Set([...builtins.filter(item=>builtinCategoryVisible(item.name)).map(item=>item.name),...customNames(),...db.subcategories.map(item=>item.id)])],targets=[];for(const key of keys){const items=[...builtinSeriesRecords(key),...(db.series[key]||[])];for(const item of items){if(item.all||item===series&&key===category||item.builtinId&&item.builtinId===series.builtinId)continue;targets.push({category:key,series:item});}}return targets;}
function chooseSeriesToMerge(category,series){const targets=availableMergeTargets(category,series);if(!targets.length){alert('Aucune autre série disponible pour la fusion.');return;}const d=dialog('Fusionner la série',`<p>Choisis la série à réunir avec <b>${esc(series.name)}</b>. Le résultat gardera le nom et l’emplacement de la série choisie. Les deux séries d’origine seront remplacées par le résultat.</p><label>Autre série</label><select id="mergeTarget">${targets.map((item,index)=>`<option value="${index}">${esc(categoryPath(item.category))} · ${esc(item.series.name)}</option>`).join('')}</select><div class="dialog-actions"><button class="button secondary" value="close">Annuler</button><button class="button primary" id="confirmMerge">Fusionner</button></div>`);d.showModal();d.querySelector('#confirmMerge').onclick=async()=>{const target=targets[Number(d.querySelector('#mergeTarget').value)];if(!target)return;const targetCategory=target.category,targetSeries=target.series;d.close();try{const [sourceQuestions,targetQuestions]=await Promise.all([seriesQuestions(category,series),seriesQuestions(targetCategory,targetSeries)]);const mergedQuestions=unique([...sourceQuestions,...targetQuestions]);if(!mergedQuestions.length){alert('Aucune question valide à fusionner.');return;}if(!confirm(`Fusionner « ${series.name} » avec « ${targetSeries.name} » ? La série choisie gardera son nom, et les deux séries d’origine seront remplacées par une série personnalisée de ${mergedQuestions.length} questions.`))return;removeSeriesFromStorage(category,series);removeSeriesFromStorage(targetCategory,targetSeries);db.series[targetCategory]??=[];db.series[targetCategory].push({name:targetSeries.name,count:mergedQuestions.length,questions:mergedQuestions});save();renderHome();if(currentView==='categoryView')openCategory(targetCategory,false);alert(`Fusion terminée : « ${targetSeries.name} » contient maintenant ${mergedQuestions.length} questions.`);}catch(error){alert(`Fusion impossible : ${error.message}`);}};}
function renameSeries(category,series){const d=dialog('Renommer la série',`<label>Nouveau nom</label><input id="renameSeriesInput" value="${esc(series.name)}"><div class="dialog-actions"><button class="button secondary" value="close">Annuler</button><button class="button primary" id="renameSeriesSave">Enregistrer</button></div>`);d.showModal();$('renameSeriesSave').onclick=()=>{const name=$('renameSeriesInput').value.trim();if(!name)return;const duplicate=[...builtinSeriesRecords(category),...(db.series[category]||[])].some(item=>item!==series&&item.builtinId!==series.builtinId&&item.name.toLocaleLowerCase('fr')===name.toLocaleLowerCase('fr'));if(duplicate){alert('Une série porte déjà ce nom dans cette catégorie.');return;}if(series.builtinId){db.builtinSeriesNames[series.builtinId]=name;for(const group of Object.values(db.series))for(const item of group)if(item.builtinId===series.builtinId)item.name=name;}else series.name=name;save();d.close();renderHome();if(currentView==='categoryView')openCategory(category,false);};}
function categoryDestinations(excluded=[]){const options=[...builtins.filter(item=>item.name!=='Tout mélange'&&builtinCategoryVisible(item.name)&&!subcategoryById(item.name)).map(item=>({id:item.name,label:categoryLabel(item.name)})),...db.categories.map(name=>({id:name,label:categoryLabel(name)})),...db.subcategories.map(item=>({id:item.id,label:categoryPath(item.id)}))];const seen=new Set();return options.filter(item=>!excluded.includes(item.id)&&!seen.has(item.id)&&seen.add(item.id));}
function transferSeries(source,series,target){
  if(source===target)return false;
  const targetList=db.series[target]||[];
  if([...builtinSeriesRecords(target),...targetList].some(item=>item.builtinId!==series.builtinId&&item.name.toLocaleLowerCase('fr')===series.name.toLocaleLowerCase('fr'))){alert('Une série porte déjà ce nom dans cette catégorie.');return false;}
  db.series[target]??=[];
  if(series.builtinId){for(const group of Object.values(db.series))for(let index=group.length-1;index>=0;index--)if(group[index].builtinId===series.builtinId)group.splice(index,1);db.builtinSeriesLocations[series.builtinId]=target;db.series[target].push({...series,name:db.builtinSeriesNames[series.builtinId]||series.name});}
  else{const sourceList=db.series[source]||[],index=sourceList.indexOf(series);if(index<0){alert('Cette série n’a pas été retrouvée dans sa catégorie actuelle.');return false;}sourceList.splice(index,1);db.series[target].push(series);}
  save();renderHome();if(currentView==='categoryView'&&currentCategory===source)openCategory(source,false);return true;
}
function moveSeries(source,series){const options=categoryDestinations([source]);if(!options.length){alert('Aucune autre catégorie de destination disponible.');return;}const d=dialog('Déplacer la série',`<p><b>${esc(series.name)}</b> · ${esc(categoryPath(source))}</p><label>Catégorie de destination</label><select id="moveDestination">${options.map(item=>`<option value="${esc(item.id)}">${esc(item.label)}</option>`).join('')}</select><div class="dialog-actions"><button class="button secondary" value="close">Annuler</button><button class="button primary" id="confirmMove">Déplacer</button></div>`);d.showModal();$('confirmMove').onclick=()=>{if(transferSeries(source,series,$('moveDestination').value))d.close();};}
async function startBuiltIn(category,series){let pool=[];for(const f of series.files||[])pool.push(...await csv(f));startQuiz(series.name==='Toutes les questions'?unique(pool):pool,`${categoryPath(category)} · ${series.name}`,20,series.name!=='Toutes les questions');}
async function categoryPool(category){let pool=[];if(category==='Tout mélange'){for(const definition of builtins.filter(item=>item.name!=='Tout mélange'&&builtinCategoryVisible(item.name)))for(const series of builtinSeriesRecords(definition.name).filter(item=>!item.all))for(const file of (series.files||[]).filter(file=>!file.startsWith('tout_melange')))pool.push(...await csv(file));for(const group of Object.values(db.series))for(const series of group){if(series.builtinId){for(const file of series.files||[])pool.push(...await csv(file));}else pool.push(...series.questions||[]);}}else{for(const key of categoryTreeKeys(category)){for(const series of builtinSeriesRecords(key))for(const file of series.files||[])pool.push(...await csv(file));for(const series of db.series[key]||[]){if(series.builtinId){for(const file of series.files||[])pool.push(...await csv(file));}else pool.push(...series.questions||[]);}}}return unique(pool);}
async function startAll(category){startQuiz(await categoryPool(category),`${categoryPath(category)} · Toutes les questions`,20,false);}
function unique(qs){const seen=new Set();return qs.filter(q=>{const k=`${q.question}|${q.options.join('|')}|${q.correct}`;if(seen.has(k))return false;seen.add(k);return true;});}
function startCustom(category,series){startQuiz(series.questions||[],`${categoryPath(category)} · ${series.name}`,series.count||series.questions?.length||20,true);}
function startQuiz(pool,label,count,repeat){if(!pool.length){alert('Aucune question disponible dans cette série.');return;}session=[];if(repeat){while(session.length<count)session.push(...shuffle(pool).slice(0,count-session.length));}else{session=shuffle(pool).slice(0,count);while(session.length<count)session.push(pool[Math.floor(Math.random()*pool.length)]);}session=session.slice(0,count);session.label=label;qIndex=0;sessionScore=0;left=300;show('quizView');clearInterval(timer);timer=setInterval(()=>{left--;paintTimer();if(left<=0)finish(true);},1000);renderQuestion();}
function shuffle(a){return [...a].sort(()=>Math.random()-.5);}
function renderQuestion(){const original=session[qIndex];const order=shuffle([0,1,2,3]);const q={question:original.question,options:order.map(i=>original.options[i]),correct:order.indexOf(original.correct)};session[qIndex]=q;selected=-1;locked=false;$('quizLabel').textContent=session.label;$('progressText').textContent=`Question ${qIndex+1} / ${session.length}`;$('progressBar').style.width=`${(qIndex+1)/session.length*100}%`;$('questionText').textContent=q.question;$('feedback').textContent='';$('nextButton').disabled=true;$('nextButton').textContent='Valider ma réponse';const host=$('answers');host.innerHTML='';q.options.forEach((answer,i)=>{const b=document.createElement('button');b.className='answer';b.textContent=answer;b.onclick=()=>{if(locked)return;selected=i;host.querySelectorAll('button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('nextButton').disabled=false;};host.append(b);});paintTimer();}
function paintTimer(){$('timer').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;}
$('nextButton').onclick=()=>{if(!locked){locked=true;const q=session[qIndex];if(selected===q.correct)sessionScore++;const buttons=$('answers').querySelectorAll('button');buttons.forEach((b,i)=>{b.disabled=true;if(i===q.correct)b.classList.add('correct');else if(i===selected)b.classList.add('wrong');});$('feedback').textContent=selected===q.correct?'Bonne réponse !':`La bonne réponse était : ${q.options[q.correct]}`;$('nextButton').textContent='Continuer';return;}if(++qIndex>=session.length)finish(false);else renderQuestion();};
function finish(timeout){clearInterval(timer);const total=session.length;const percent=Math.round(sessionScore/total*100);const d=$('dialog');$('dialogContent').innerHTML=`<h2>${timeout?'Temps écoulé':'Série terminée'}</h2><p><b>${esc(session.label)}</b></p><p>Score : <b>${sessionScore} / ${total}</b> (${percent} %)</p><div class="dialog-actions"><button class="button secondary" id="finishClose">Fermer</button><button class="button primary" id="finishHome">Catégories</button></div>`;d.showModal();$('finishClose').onclick=()=>{d.close();openCategory(currentCategory);};$('finishHome').onclick=()=>{d.close();show('homeView');renderHome();};show('categoryView');}
$('abandonButton').onclick=()=>{if(currentView==='quizView'&&history.state?.revisionExpressView==='quizView')history.back();else openCategory(currentCategory);};$('backHome').onclick=()=>{if(currentView==='categoryView'&&history.state?.revisionExpressView==='categoryView')history.back();else show('homeView');};$('homeLink').onclick=e=>{e.preventDefault();clearInterval(timer);show('homeView');};
function dialog(title,body){const f=$('dialogContent');f.innerHTML=`<h2>${esc(title)}</h2>${body}`;return $('dialog');}
$('dialogContent').addEventListener('click',e=>{if(e.target.closest('[value="close"]')){$('dialog').close();}});
function categoryActions(name){
  const builtin=isBuiltinCategory(name),subcategory=!!subcategoryById(name);
  const managed=builtin||db.categories.includes(name)||subcategory;
  const canNest=name!=='Tout mélange',canMove=subcategory||(builtin&&canNest);
  const body=`<p>${managed?'Gère cette catégorie, ses sous-catégories et ses séries.':'Ouvre cette matière ou ajoute-lui tes propres contenus.'}</p><div class="dialog-actions stack"><button class="button primary wide" data-act="open">Ouvrir la catégorie</button><button class="button secondary wide" data-act="create">Créer une nouvelle série</button>${canNest?'<button class="button secondary wide" data-act="createSubcategory">Créer une sous-catégorie</button>':''}<button class="button secondary wide" data-act="share">Partager la catégorie</button>${canMove?`<button class="button secondary wide" data-act="move">${subcategory?'Déplacer la sous-catégorie':'Déplacer la catégorie'}</button>`:''}${managed?'<button class="button secondary wide" data-act="rename">Renommer</button><button class="button secondary wide" data-act="delete">Supprimer</button>':''}<button type="button" class="button secondary wide" data-act="close">Fermer</button></div>`;
  const d=dialog(categoryPath(name),body);d.showModal();
  d.querySelector('[data-act="close"]').onclick=()=>d.close();
  d.querySelector('[data-act="open"]').onclick=()=>{d.close();openCategory(name);};
  d.querySelector('[data-act="create"]').onclick=()=>{d.close();editSeries(name,null);};
  d.querySelector('[data-act="createSubcategory"]')?.addEventListener('click',()=>{d.close();createSubcategory(name);});
  d.querySelector('[data-act="move"]')?.addEventListener('click',()=>{d.close();if(subcategory)moveSubcategory(name);else moveBuiltinCategory(name);});
  d.querySelector('[data-act="share"]').onclick=async()=>{d.close();try{const list=[];for(const key of categoryTreeKeys(name)){for(const series of builtinSeriesRecords(key)){if(series.all)continue;const questions=(await Promise.all((series.files||[]).map(csv))).flat();list.push({name:series.name,count:20,questions});}for(const series of db.series[key]||[]){const questions=series.questions||((await Promise.all((series.files||[]).map(csv))).flat());list.push({name:series.name,count:series.count||20,questions});}}if(!list.length)throw new Error('La catégorie ne contient aucune série à partager.');await publishShare({category:categoryPath(name),series:list});}catch(error){alert(`Partage impossible : ${error.message}`);}};
  d.querySelector('[data-act="rename"]')?.addEventListener('click',()=>{d.close();renameCategory(name);});
  d.querySelector('[data-act="delete"]')?.addEventListener('click',()=>{d.close();deleteCategory(name);});
}
function addSubcategory(parent,name){const id=`subcategory:${crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`}`;db.subcategories.push({id,parent,name});db.series[id]=[];return id;}
function createSubcategory(parent){const d=dialog('Créer une sous-catégorie',`<p>Elle sera ajoutée dans <b>${esc(categoryPath(parent))}</b>.</p><label>Nom de la sous-catégorie</label><input id="subcategoryName" placeholder="Ex. Chapitre 1"><div class="dialog-actions"><button class="button secondary" value="close">Annuler</button><button class="button primary" id="saveSubcategory">Créer</button></div>`);d.showModal();$('saveSubcategory').onclick=()=>{const name=$('subcategoryName').value.trim();if(!name){alert('Saisis un nom.');return;}if(childCategories(parent).some(child=>child.name.toLocaleLowerCase('fr')===name.toLocaleLowerCase('fr'))){alert('Une sous-catégorie porte déjà ce nom ici.');return;}addSubcategory(parent,name);save();d.close();renderHome();openCategory(parent);};}
function createCategory(){const d=dialog('Créer une catégorie',`<p>Ajoute une nouvelle catégorie au menu principal.</p><label>Nom de la catégorie</label><input id="newCategoryName" placeholder="Ex. Italien"><div class="dialog-actions"><button class="button secondary" value="close">Annuler</button><button class="button primary" id="saveCategory">Créer</button></div>`);d.showModal();$('saveCategory').onclick=()=>{const name=$('newCategoryName').value.trim();if(!name){alert('Saisis un nom.');return;}if([...builtins.flatMap(item=>[item.name,categoryLabel(item.name)]),...customNames()].some(existing=>existing.toLocaleLowerCase('fr')===name.toLocaleLowerCase('fr'))){alert('Cette catégorie existe déjà.');return;}db.categories.push(name);db.series[name]=[];save();d.close();renderHome();};}
function moveSubcategory(id){const item=subcategoryById(id);if(!item)return;const excluded=[...categoryTreeKeys(id),item.parent];const options=categoryDestinations(excluded);if(item.builtin)options.unshift({id:'__main_menu__',label:'Menu principal'});if(!options.length){alert('Aucune destination disponible pour cette sous-catégorie.');return;}const d=dialog('Déplacer la sous-catégorie',`<p><b>${esc(categoryPath(id))}</b></p><label>Nouvelle catégorie parente</label><select id="moveDestination">${options.map(option=>`<option value="${esc(option.id)}">${esc(option.label)}</option>`).join('')}</select><div class="dialog-actions"><button class="button secondary" value="close">Annuler</button><button class="button primary" id="confirmMove">Déplacer</button></div>`);d.showModal();$('confirmMove').onclick=()=>{const destination=$('moveDestination').value;if(destination==='__main_menu__'&&item.builtin){db.builtinCategoryNames[id]=item.name;db.subcategories=db.subcategories.filter(child=>child.id!==id);save();d.close();renderHome();if(currentView==='categoryView')openCategory(currentCategory,false);return;}if(excluded.includes(destination))return;if(childCategories(destination).some(child=>child.id!==id&&child.name.toLocaleLowerCase('fr')===item.name.toLocaleLowerCase('fr'))){alert('Une sous-catégorie porte déjà ce nom dans cette destination.');return;}item.parent=destination;save();d.close();renderHome();if(currentView==='categoryView')openCategory(currentCategory,false);};}
function moveBuiltinCategory(id){const options=categoryDestinations(categoryTreeKeys(id));if(!options.length){alert('Aucune destination disponible.');return;}const d=dialog('Déplacer la catégorie',`<p><b>${esc(categoryLabel(id))}</b> deviendra une sous-catégorie.</p><label>Catégorie parente</label><select id="moveDestination">${options.map(option=>`<option value="${esc(option.id)}">${esc(option.label)}</option>`).join('')}</select><div class="dialog-actions"><button class="button secondary" value="close">Annuler</button><button class="button primary" id="confirmMove">Déplacer</button></div>`);d.showModal();$('confirmMove').onclick=()=>{const parent=$('moveDestination').value;const name=categoryLabel(id);if(childCategories(parent).some(child=>child.name.toLocaleLowerCase('fr')===name.toLocaleLowerCase('fr'))){alert('Une sous-catégorie porte déjà ce nom dans cette destination.');return;}db.subcategories.push({id,parent,name,builtin:true});save();d.close();renderHome();if(currentView==='categoryView')openCategory(currentCategory,false);};}
function beginDrag(source,pointerId,x,y,handle,inputType){activeDrag={pointerId,source,startX:x,startY:y,dragging:false,target:null,handle,inputType};}
function enableDragHandle(tile){const handle=tile.querySelector('.drag-handle');if(!handle)return;handle.addEventListener('pointerdown',event=>{if(event.pointerType==='touch'||!event.isPrimary||(event.pointerType==='mouse'&&event.button!==0)||activeDrag)return;event.stopPropagation();beginDrag(tile._dragInfo,event.pointerId,event.clientX,event.clientY,handle,'pointer');try{handle.setPointerCapture(event.pointerId);}catch{}});handle.addEventListener('touchstart',event=>{if(activeDrag)return;const touch=event.changedTouches[0];if(!touch)return;event.stopPropagation();beginDrag(tile._dragInfo,`touch-${touch.identifier}`,touch.clientX,touch.clientY,handle,'touch');},{passive:true});}
function dragTargetAt(x,y){const element=document.elementFromPoint(x,y);const tile=element?.closest('.subcategory-tile, .series-tile');return tile?._dragInfo?tile:null;}
function clearDragHighlights(){document.querySelectorAll('.drop-target').forEach(tile=>tile.classList.remove('drop-target'));}
function persistDragChanges(){save();renderHome();if(currentView==='categoryView')openCategory(currentCategory,false);}
function reorderSeries(source,target,after){const items=[...builtinSeriesRecords(source.category),...(db.series[source.category]||[])];const from=items.findIndex(item=>seriesOrderKey(item)===seriesOrderKey(source.series)),targetIndex=items.findIndex(item=>seriesOrderKey(item)===seriesOrderKey(target.series));if(from<0||targetIndex<0||from===targetIndex)return;const [moving]=items.splice(from,1);const adjustedTarget=items.findIndex(item=>seriesOrderKey(item)===seriesOrderKey(target.series));items.splice(adjustedTarget+(after?1:0),0,moving);db.seriesOrder[source.category]=items.map(seriesOrderKey);persistDragChanges();}
function reorderSubcategories(source,target,after){const parent=source.parent;const siblings=childCategories(parent);const from=siblings.findIndex(item=>item.id===source.id);if(from<0||source.id===target.id)return;siblings.splice(from,1);const targetIndex=siblings.findIndex(item=>item.id===target.id);if(targetIndex<0)return;siblings.splice(targetIndex+(after?1:0),0,subcategoryById(source.id));let index=0;db.subcategories=db.subcategories.map(item=>item.parent===parent?siblings[index++]:item);persistDragChanges();}
function updateDrag(x,y){if(!activeDrag.dragging&&Math.hypot(x-activeDrag.startX,y-activeDrag.startY)>8){activeDrag.dragging=true;activeDrag.source.tile.classList.add('dragging');}if(!activeDrag.dragging)return;if(y<70)window.scrollBy(0,-14);else if(y>innerHeight-70)window.scrollBy(0,14);const target=dragTargetAt(x,y);if(target!==activeDrag.target){activeDrag.target?.classList.remove('drop-target');activeDrag.target=target;if(target&&target!==activeDrag.source.tile)target.classList.add('drop-target');}}
function clearActiveDrag(){if(!activeDrag)return;activeDrag.source.tile.classList.remove('dragging');activeDrag.target?.classList.remove('drop-target');clearDragHighlights();activeDrag=null;}
function finishDrag(x,y,event){const drag=activeDrag;if(!drag)return;if(drag.dragging){const target=dragTargetAt(x,y)||drag.target;dragClickGuardUntil=Date.now()+500;dropDraggedItem(drag.source,target,{clientY:y});}clearActiveDrag();}
function dropDraggedItem(source,target,event){if(!target||target===source.tile)return;const destination=target._dragInfo;const after=event.clientY>target.getBoundingClientRect().top+target.getBoundingClientRect().height/2;if(source.type==='series'){if(destination.type==='subcategory'){const list=db.series[destination.id]||[];if(list.some(item=>item.name.toLocaleLowerCase('fr')===source.series.name.toLocaleLowerCase('fr'))){alert('Une série porte déjà ce nom dans cette sous-catégorie.');return;}transferSeries(source.category,source.series,destination.id);return;}if(destination.type==='series'&&destination.category===source.category)reorderSeries(source,destination,after);return;}if(source.type==='subcategory'&&destination.type==='subcategory'){if(source.parent===destination.parent){reorderSubcategories(source,destination,after);return;}if(categoryTreeKeys(source.id).includes(destination.id))return;if(childCategories(destination.id).some(item=>item.id!==source.id&&item.name.toLocaleLowerCase('fr')===subcategoryById(source.id)?.name.toLocaleLowerCase('fr'))){alert('Une sous-catégorie porte déjà ce nom dans cette destination.');return;}const item=subcategoryById(source.id);if(!item)return;item.parent=destination.id;persistDragChanges();}}
document.addEventListener('pointermove',event=>{if(!activeDrag||activeDrag.inputType!=='pointer'||event.pointerId!==activeDrag.pointerId)return;updateDrag(event.clientX,event.clientY);});
document.addEventListener('pointerup',event=>{if(!activeDrag||activeDrag.inputType!=='pointer'||event.pointerId!==activeDrag.pointerId)return;finishDrag(event.clientX,event.clientY,event);});
document.addEventListener('pointercancel',event=>{if(activeDrag?.inputType==='pointer'&&event.pointerId===activeDrag.pointerId)clearActiveDrag();});
document.addEventListener('touchmove',event=>{if(!activeDrag||activeDrag.inputType!=='touch')return;const touch=[...event.changedTouches].find(item=>`touch-${item.identifier}`===activeDrag.pointerId);if(!touch)return;updateDrag(touch.clientX,touch.clientY);if(activeDrag.dragging)event.preventDefault();},{passive:false});
document.addEventListener('touchend',event=>{if(!activeDrag||activeDrag.inputType!=='touch')return;const touch=[...event.changedTouches].find(item=>`touch-${item.identifier}`===activeDrag.pointerId);if(touch)finishDrag(touch.clientX,touch.clientY,event);});
document.addEventListener('touchcancel',()=>{if(activeDrag?.inputType==='touch')clearActiveDrag();});
function createMore(){
  const options=[...builtins.filter(item=>item.name!=='Tout mélange'&&builtinCategoryVisible(item.name)&&!subcategoryById(item.name)).map(item=>({id:item.name,label:categoryLabel(item.name)})),...db.categories.map(name=>({id:name,label:categoryLabel(name)}))];
  const d=dialog('Créer plus',`<p>Choisis la catégorie à enrichir, ou crée-en une nouvelle.</p><label>Catégorie</label><select id="createCategorySelect">${options.map(option=>`<option value="${esc(option.id)}">${esc(option.label)}</option>`).join('')}</select><label>Nouvelle catégorie (facultatif)</label><input id="newCategory" placeholder="Ex. Italien"><div class="dialog-actions"><button class="button secondary" value="close">Annuler</button><button class="button primary" id="continueCreate">Continuer</button></div>`);d.showModal();
  $('continueCreate').onclick=()=>{const newName=$('newCategory').value.trim();const name=newName||$('createCategorySelect').value;if(!name){alert('Saisis un nom de catégorie.');return;}if(newName){const exists=[...builtins.flatMap(item=>[item.name,categoryLabel(item.name)]),...customNames()].some(label=>label.toLocaleLowerCase('fr')===name.toLocaleLowerCase('fr'));if(exists){alert('Cette catégorie existe déjà.');return;}db.categories.push(name);db.series[name]=[];save();renderHome();}d.close();editSeries(name,null);};
}
function editSeries(category,series){
  let qs=series?structuredClone(series.questions||[]):[];
  if(!qs.length)qs=[{question:'',options:['','','',''],correct:0}];
  let ix=0,destinationCategory=category,showCsvDestination=false;
  let draftName=series?.name||'',draftCount=series?.count||20;
  const isNew=!series;
  function render(){
    const q=qs[ix];
    const destinations=showCsvDestination?`<label>Emplacement de la série</label><select id="seriesDestination">${categoryDestinations().map(option=>`<option value="${esc(option.id)}" ${option.id===destinationCategory?'selected':''}>${esc(option.label)}</option>`).join('')}</select>`:'';
    const body=`<label>Nom de la série</label><input id="seriesName" value="${esc(draftName)}" placeholder="Ex. Vocabulaire"><label>Nombre de questions dans la série</label><input id="seriesCount" type="number" min="1" max="200" value="${draftCount}">${destinations}<label>${isNew?'Importer des questions depuis un CSV':'Ajouter des questions depuis un CSV'}</label><input id="seriesCsv" type="file" accept=".csv,text/csv" class="hidden"><button class="button secondary wide" type="button" id="importCsvButton">${isNew?'Importer un fichier CSV':'Ajouter un fichier CSV'}</button><div class="editor-progress">Question ${ix+1} / ${qs.length}</div><label>Question</label><textarea id="editQuestion">${esc(q.question)}</textarea>${q.options.map((a,i)=>`<label>Réponse ${i+1}</label><input class="editAnswer" value="${esc(a)}">`).join('')}<label>Bonne réponse</label><select id="correctAnswer">${q.options.map((_,i)=>`<option value="${i}" ${q.correct===i?'selected':''}>Réponse ${i+1}</option>`).join('')}</select><div class="question-nav"><button class="button secondary" id="previousQ" ${ix===0?'disabled':''}>← Précédente</button><button class="button secondary" id="nextQ">Question suivante →</button></div><div class="dialog-actions"><button class="button secondary" value="close">Annuler</button>${series?'<button class="button secondary" id="deleteSeries">Supprimer</button>':''}<button class="button primary" id="saveSeries">Enregistrer</button></div>`;
    const d=dialog(series?'Modifier la série':'Nouvelle série',body);
    if(!d.open)d.showModal();
    function store(){qs[ix]={question:$('editQuestion').value,options:[...d.querySelectorAll('.editAnswer')].map(x=>x.value),correct:Number($('correctAnswer').value)};draftName=$('seriesName').value;draftCount=$('seriesCount').value;}
    d.querySelector('#seriesDestination')?.addEventListener('change',event=>destinationCategory=event.target.value);
    d.querySelector('#importCsvButton')?.addEventListener('click',()=>$('seriesCsv').click());
    d.querySelector('#seriesCsv')?.addEventListener('change',async event=>{
      const file=event.target.files?.[0];if(!file)return;
      try{
        const imported=parseCsv(await file.text());
        if(!imported.length)throw new Error('Aucune question valide trouvée. Vérifie le format du fichier.');
        if(isNew){
          const hasDraft=qs.some(item=>item.question.trim()||item.options.some(answer=>answer.trim()))||$('editQuestion').value.trim()||[...d.querySelectorAll('.editAnswer')].some(input=>input.value.trim());
          if(hasDraft&&!confirm('Importer ce CSV remplacera les questions déjà saisies. Continuer ?'))return;
          qs=imported;ix=0;showCsvDestination=true;destinationCategory=category;$('seriesCount').value=Math.min(200,imported.length);
        }else{store();ix=qs.length;qs.push(...imported);}
        $('seriesName').value=$('seriesName').value.trim()||file.name.replace(/\.csv$/i,'');
        draftName=$('seriesName').value;draftCount=$('seriesCount').value;
        render();
      }catch(error){alert(`Import CSV impossible : ${error.message}`);}
      finally{event.target.value='';}
    });
    d.querySelector('#previousQ').onclick=()=>{store();if(ix>0){ix--;render();}};
    d.querySelector('#nextQ').onclick=()=>{store();if(ix===qs.length-1)qs.push({question:'',options:['','','',''],correct:0});ix++;render();};
    d.querySelector('#saveSeries').onclick=()=>{
      store();const name=draftName.trim();
      if(!name||qs.some(question=>!question.question.trim()||question.options.some(answer=>!answer.trim()))){alert('Complète le nom et toutes les questions avec leurs quatre réponses.');return;}
      const count=Math.max(1,Math.min(200,Number(draftCount)||20));
      const targetCategory=isNew&&showCsvDestination?destinationCategory:category;
      db.series[targetCategory]??=[];
      const previous=series?db.series[targetCategory].findIndex(item=>item.name===series.name):-1;
      const saved={name,count,questions:qs};
      if(previous>=0)db.series[targetCategory][previous]=saved;else db.series[targetCategory].push(saved);
      save();d.close();renderHome();
      if(isNew&&showCsvDestination)openCategory(targetCategory);else if(currentCategory===category)openCategory(category);
    };
    d.querySelector('#deleteSeries')?.addEventListener('click',()=>{store();if(confirm(`Supprimer « ${series.name} » ?`)){db.series[category]=db.series[category].filter(item=>item.name!==series.name);save();d.close();renderHome();openCategory(category);}});
  }
  render();
}
function renameCategory(name){
  const entry=subcategoryById(name),oldLabel=categoryLabel(name);
  const d=dialog('Renommer la catégorie',`<label>Nouveau nom</label><input id="renameInput" value="${esc(oldLabel)}"><div class="dialog-actions"><button class="button secondary" value="close">Annuler</button><button class="button primary" id="renameGo">Renommer</button></div>`);d.showModal();
  $('renameGo').onclick=()=>{
    const next=$('renameInput').value.trim();if(!next||next===oldLabel)return;
    if(entry){if(childCategories(entry.parent).some(child=>child.id!==name&&child.name.toLocaleLowerCase('fr')===next.toLocaleLowerCase('fr'))){alert('Une sous-catégorie porte déjà ce nom ici.');return;}entry.name=next;}
    else if(isBuiltinCategory(name)){const used=[...builtins.filter(item=>item.name!==name).flatMap(item=>[item.name,categoryLabel(item.name)]),...customNames()].some(label=>label.toLocaleLowerCase('fr')===next.toLocaleLowerCase('fr'));if(used){alert('Ce nom de catégorie est déjà utilisé.');return;}db.builtinCategoryNames[name]=next;}
    else{if([...builtins.flatMap(item=>[item.name,categoryLabel(item.name)]),...customNames().filter(item=>item!==name)].some(label=>label.toLocaleLowerCase('fr')===next.toLocaleLowerCase('fr'))){alert('Ce nom de catégorie est déjà utilisé.');return;}db.categories=db.categories.map(item=>item===name?next:item);db.series[next]=db.series[name]||[];delete db.series[name];db.subcategories.forEach(child=>{if(child.parent===name)child.parent=next;});if(currentCategory===name)currentCategory=next;}
    save();d.close();renderHome();if(currentView==='categoryView')openCategory(currentCategory,false);
  };
}
function deleteCategory(name){
  if(!confirm(`Supprimer « ${categoryPath(name)} » et toutes ses sous-catégories et séries ?`))return;
  const keys=categoryTreeKeys(name),builtinIds=new Set();
  for(const key of keys){if(isBuiltinCategory(key)&&!db.deletedBuiltinCategories.includes(key))db.deletedBuiltinCategories.push(key);for(const series of db.series[key]||[])if(series.builtinId)builtinIds.add(series.builtinId);delete db.series[key];}
  for(const category of builtins)for(const series of category.series){const id=builtinSeriesId(category.name,series);if(keys.includes(category.name)||builtinIds.has(id)){builtinIds.add(id);if(!db.deletedBuiltinSeries.includes(id))db.deletedBuiltinSeries.push(id);delete db.builtinSeriesLocations[id];}}
  for(const [location,seriesList] of Object.entries(db.series))db.series[location]=seriesList.filter(series=>!builtinIds.has(series.builtinId));
  db.subcategories=db.subcategories.filter(item=>!keys.includes(item.id));db.categories=db.categories.filter(item=>item!==name);delete db.builtinCategoryNames[name];
  const currentWasDeleted=keys.includes(currentCategory);if(currentWasDeleted){currentCategory=null;show('homeView');}save();renderHome();if(!currentWasDeleted&&currentView==='categoryView')openCategory(currentCategory,false);
}
function mySeries(){const entries=Object.entries(db.series).flatMap(([c,ss])=>ss.filter(series=>!series.builtinId).map(s=>({c,s})));if(!entries.length){alert('Tu n’as pas encore créé de série.');return;}const body=`<div class="series-grid">${entries.map((x,i)=>`<button class="series-tile" data-i="${i}"><div class="tile-title">${esc(categoryPath(x.c))} · ${esc(x.s.name)}</div><div class="tile-sub">${x.s.count} questions · Modifier / jouer</div></button>`).join('')}</div><div class="dialog-actions"><button class="button secondary" value="close">Fermer</button></div>`;const d=dialog('Mes séries',body);d.showModal();d.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{const x=entries[Number(b.dataset.i)];d.close();const pick=dialog(x.s.name,`<p>${esc(categoryPath(x.c))} · ${x.s.count} questions</p><div class="dialog-actions"><button class="button secondary" value="close">Fermer</button><button class="button secondary" id="editMine">Modifier</button><button class="button secondary" id="locationMine">Voir l’emplacement</button><button class="button primary" id="playMine">Jouer</button></div>`);pick.showModal();$('editMine').onclick=()=>{pick.close();editSeries(x.c,x.s);};$('locationMine').onclick=()=>{pick.close();currentCategory=x.c;openCategory(x.c);};$('playMine').onclick=()=>{pick.close();currentCategory=x.c;startCustom(x.c,x.s);};});}
function bindBlankLongPress(container,selector,action){let hold=null,triggered=false,startX=0,startY=0;const clear=()=>{if(hold!==null)clearTimeout(hold);hold=null;};const isBlankTarget=target=>target instanceof Element&&target.matches(selector)&&!target.closest('button,a,input,textarea,select,option,label,[role="button"]');container.addEventListener('pointerdown',event=>{if(!event.isPrimary||event.button!==0||!isBlankTarget(event.target))return;clear();triggered=false;startX=event.clientX;startY=event.clientY;hold=setTimeout(()=>{hold=null;triggered=true;action();},650);});container.addEventListener('pointermove',event=>{if(hold!==null&&Math.hypot(event.clientX-startX,event.clientY-startY)>12)clear();});['pointerup','pointercancel','pointerleave'].forEach(type=>container.addEventListener(type,clear));container.addEventListener('contextmenu',event=>{if(!isBlankTarget(event.target))return;event.preventDefault();clear();if(!triggered){triggered=true;action();}});}
bindBlankLongPress($('homeView'),'#homeView, #categoryGrid, .hero, .toolbar, .backup-panel',createCategory);
bindBlankLongPress($('categoryView'),'#categoryView, #categoryView *',()=>{if(currentCategory)categoryActions(currentCategory);});
['categoryGrid','subcategoryGrid','seriesGrid'].forEach(id=>{const grid=$(id);grid.addEventListener('selectstart',event=>event.preventDefault());grid.addEventListener('contextmenu',event=>{if(event.target.closest('.category-tile, .series-tile'))event.preventDefault();},true);});
$('createButton').onclick=createMore;$('mySeriesButton').onclick=mySeries;renderHome();
$('exportButton').onclick=()=>{const payload={format:'revision-express-backup',version:1,exportedAt:new Date().toISOString(),data:db};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`revision-express-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);};
$('importButton').onclick=()=>$('importFile').click();
$('importFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const parsed=JSON.parse(await file.text());const incoming=parsed.data||parsed;if(!Array.isArray(incoming.categories)||!incoming.series||typeof incoming.series!=='object')throw new Error('format');if(!confirm('Importer cette sauvegarde ? Les séries portant le même nom seront remplacées.'))return;const subcategoryMap=new Map([...db.subcategories,...(incoming.subcategories||[])].map(item=>[item.id,item]));db={...db,categories:[...new Set([...db.categories,...incoming.categories])],series:{...db.series,...incoming.series},subcategories:[...subcategoryMap.values()],deletedBuiltinCategories:[...new Set([...db.deletedBuiltinCategories,...(incoming.deletedBuiltinCategories||[])])],builtinCategoryNames:{...db.builtinCategoryNames,...(incoming.builtinCategoryNames||{})},deletedBuiltinSeries:[...new Set([...db.deletedBuiltinSeries,...(incoming.deletedBuiltinSeries||[])])],builtinSeriesNames:{...db.builtinSeriesNames,...(incoming.builtinSeriesNames||{})},builtinSeriesLocations:{...db.builtinSeriesLocations,...(incoming.builtinSeriesLocations||{})},builtinSeriesOrder:{...db.builtinSeriesOrder,...(incoming.builtinSeriesOrder||{})},seriesOrder:{...db.seriesOrder,...(incoming.seriesOrder||{})}};save();renderHome();alert('Sauvegarde importée.');}catch{alert('Ce fichier ne contient pas une sauvegarde Révision Express valide.');}finally{e.target.value='';}};
if(navigator.storage?.persist){navigator.storage.persist().catch(()=>{});}
function showUpdateReady(){updateAvailable=true;const button=$('updateButton');button.textContent='Installer la mise à jour';button.disabled=false;}
function observeInstallingWorker(worker){if(!worker)return;worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)showUpdateReady();else if(worker.state==='redundant'&&!updateAvailable){const button=$('updateButton');button.textContent='Vérifier les mises à jour';button.disabled=false;}});if(worker.state==='installed'&&navigator.serviceWorker.controller)showUpdateReady();}
async function checkForAppUpdate(){const button=$('updateButton');if(updateAvailable&&swRegistration?.waiting){reloadForUpdate=true;button.textContent='Installation…';button.disabled=true;swRegistration.waiting.postMessage({type:'SKIP_WAITING'});return;}if(!swRegistration)return;button.disabled=true;button.textContent='Recherche…';try{await swRegistration.update();if(swRegistration.waiting){showUpdateReady();return;}if(swRegistration.installing){button.textContent='Téléchargement…';observeInstallingWorker(swRegistration.installing);return;}button.textContent='Application à jour';setTimeout(()=>{if(!updateAvailable){button.textContent='Vérifier les mises à jour';button.disabled=false;}},2200);}catch(error){button.textContent='Vérifier les mises à jour';button.disabled=false;alert(`Vérification impossible : ${error.message}`);}}
if('serviceWorker' in navigator){$('updateButton').onclick=checkForAppUpdate;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(reloadForUpdate)location.reload();});window.addEventListener('load',async()=>{try{swRegistration=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});$('updateButton').classList.remove('hidden');if(swRegistration.waiting)showUpdateReady();swRegistration.addEventListener('updatefound',()=>observeInstallingWorker(swRegistration.installing));if(swRegistration.installing)observeInstallingWorker(swRegistration.installing);}catch(error){console.warn('Mise à jour PWA indisponible',error);}});}
const installButton=$('installButton');
const isIosDevice=/iPhone|iPad|iPod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const isStandaloneApp=navigator.standalone===true||window.matchMedia('(display-mode: standalone)').matches;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;installButton.classList.remove('hidden');});
installButton.onclick=async()=>{if(deferredInstall){deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;return;}if(isIosDevice&&!isStandaloneApp){const d=dialog('Installer Révision Express',`<p>Sur iPhone, l’ajout se fait depuis le menu de partage de Safari :</p><ol><li>Ouvre cette page dans Safari, puis touche <b>Partager</b> (le carré avec la flèche vers le haut).</li><li>Fais défiler les actions et choisis <b>Ajouter à l’écran d’accueil</b>.</li><li>Confirme avec <b>Ajouter</b>. Tu peux activer « Ouvrir comme app web » si l’option est proposée.</li></ol><div class="dialog-actions"><button class="button primary" value="close">Compris</button></div>`);d.showModal();}};
if(isIosDevice&&!isStandaloneApp)installButton.classList.remove('hidden');
window.addEventListener('appinstalled',()=>installButton.classList.add('hidden'));
async function firebaseShareModule(){return import('./firebase-share.js');}
async function publishShare(payload){const {createShare}=await firebaseShareModule();const id=await createShare(payload);const url=new URL(location.href);url.search='';url.searchParams.set('share',id);if(navigator.share)await navigator.share({title:`${payload.category} · Révision Express`,text:'Importe cette série dans Révision Express.',url:url.href});else{await navigator.clipboard.writeText(url.href);alert('Lien de partage copié.');}}
function shareImportOptions(sharedName){const existingNames=[...builtins.flatMap(item=>[item.name,categoryLabel(item.name)]),...db.categories].map(name=>name.toLocaleLowerCase('fr'));const options=[];if(!existingNames.includes(sharedName.toLocaleLowerCase('fr')))options.push({value:'new-category',label:`Nouvelle catégorie principale : ${sharedName}`});for(const parent of categoryDestinations()){const subcategory=!!subcategoryById(parent.id);options.push({value:`${subcategory?'subcategory':'category'}:${parent.id}`,label:`${subcategory?'Sous-catégorie':'Catégorie principale'} existante : ${parent.label}`});if(!childCategories(parent.id).some(child=>child.name.toLocaleLowerCase('fr')===sharedName.toLocaleLowerCase('fr')))options.push({value:`new-subcategory:${parent.id}`,label:`Nouvelle sous-catégorie « ${sharedName} » dans ${parent.label}`});}return options;}
async function openIncomingShare(){const id=new URL(location.href).searchParams.get('share');if(!id)return;try{const {readShare}=await firebaseShareModule();const data=await readShare(id);const sharedName=String(data.category||'Série partagée');const choices=shareImportOptions(sharedName);const rows=(data.series||[]).map(item=>`<li>${esc(item.name)} — ${item.questions?.length||0} questions</li>`).join('');const d=dialog('Série partagée',`<p>La catégorie <b>${esc(sharedName)}</b> contient :</p><ul>${rows}</ul><label>Choisis où importer ce partage</label><select id="shareDestination">${choices.map(option=>`<option value="${esc(option.value)}">${esc(option.label)}</option>`).join('')}</select><div class="dialog-actions"><button type="button" class="button secondary" id="cancelShared">Annuler</button><button type="button" class="button primary" id="importShared">Importer</button></div>`);d.showModal();d.querySelector('#cancelShared').onclick=()=>{d.close();history.replaceState({},'',location.pathname);};d.querySelector('#importShared').onclick=()=>{const choice=$('shareDestination').value;let target;if(choice==='new-category'){target=sharedName;db.categories.push(target);db.series[target]??=[];}else if(choice.startsWith('new-subcategory:')){target=addSubcategory(choice.slice('new-subcategory:'.length),sharedName);}else{target=choice.slice(choice.indexOf(':')+1);}db.series[target]??=[];for(const incoming of data.series||[]){const item={name:String(incoming.name),count:Number(incoming.count)||20,questions:Array.isArray(incoming.questions)?incoming.questions:[]};const old=db.series[target].findIndex(series=>series.name===item.name);if(old>=0)db.series[target][old]=item;else db.series[target].push(item);}save();renderHome();d.close();history.replaceState({},'',location.pathname);alert(`Partage importé dans « ${categoryPath(target)} ».`);};}catch(e){alert(`Impossible d’ouvrir ce partage : ${e.message}`);}}
openIncomingShare();
